package api

import (
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/more-than-code/bot-control-plane/api/internal/audit"
	"github.com/more-than-code/bot-control-plane/api/internal/authz"
	"github.com/more-than-code/bot-control-plane/api/internal/catalog"
	"github.com/more-than-code/bot-control-plane/api/internal/secret"
	"github.com/more-than-code/bot-control-plane/api/internal/store"
)

// Env set creation with key names only (api-v1 v1.27 item 4). There is no
// value field: a key is generated by the API or left as a placeholder, so
// no value passes through the caller, and a delegated (MCP) caller only
// gets a plan to confirm.

const maxCreateKeys = 64

// envCreateKey is one normalized request key. It is also the stored plan
// body, so it holds names, generate objects and flags, never a value.
type envCreateKey struct {
	Key      string            `json:"key"`
	Generate *catalog.Generate `json:"generate,omitempty"`
	IsSecret bool              `json:"is_secret"`
}

type envCreatePlanBody struct {
	Keys []envCreateKey `json:"keys"`
}

func (s *Server) handleEnvSetCreate(w http.ResponseWriter, r *http.Request) {
	p, id, ok := s.catalogProject(w, r)
	if !ok {
		return
	}
	if err := authz.Authorize(r.Context(), p.User.ID, id, authz.CapMembers); err != nil {
		s.writeAuth(w, err)
		return
	}
	delegated := p.Session.Kind == store.KindDelegated
	if !delegated && !requireConsole(w, p) {
		return
	}
	var body struct {
		Name string `json:"name"`
		Keys []struct {
			Key      string            `json:"key"`
			Generate *catalog.Generate `json:"generate"`
			IsSecret *bool             `json:"is_secret"`
		} `json:"keys"`
		Key string `json:"idempotency_key"`
	}
	if !decodeJSON(w, r, &body) {
		return
	}
	if !catalog.ValidName(body.Name) {
		writeCode(w, "bad_request", "invalid name")
		return
	}
	if len(body.Keys) == 0 || len(body.Keys) > maxCreateKeys {
		writeCode(w, "bad_request", "keys must list 1 to 64 keys")
		return
	}
	keys := make([]envCreateKey, 0, len(body.Keys))
	seen := map[string]bool{}
	for _, k := range body.Keys {
		if !envKeyOK(w, k.Key) {
			return
		}
		if seen[k.Key] {
			writeCode(w, "bad_request", "duplicate key "+k.Key)
			return
		}
		seen[k.Key] = true
		item := envCreateKey{Key: k.Key, Generate: k.Generate, IsSecret: true}
		if k.Generate != nil {
			if err := k.Generate.Validate(); err != nil {
				s.writeField(w, err)
				return
			}
			if k.IsSecret != nil && !*k.IsSecret {
				writeCode(w, "bad_request", "a generated value is secret")
				return
			}
		} else if k.IsSecret != nil {
			item.IsSecret = *k.IsSecret
		}
		keys = append(keys, item)
	}
	if needsSecretsKey(keys) && s.Secrets == nil {
		s.logger().Error("secrets key not configured")
		writeCode(w, "unavailable", errSecretsKey.Error())
		return
	}
	if delegated {
		s.issueEnvSetCreate(w, r, p, id, body.Name, keys, body.Key)
		return
	}
	set, err := s.createEnvSetNames(r, id, body.Name, keys, nil, p.User.ID)
	if err != nil {
		s.envSetCreateErr(w, body.Name, err)
		return
	}
	s.auditEnvSetCreate(r, p, id, body.Name, keys, audit.ViaConsole)
	writeOK(w, http.StatusCreated, set)
}

// createEnvSetNames generates and seals the values, then creates the set.
// Generated values are drawn at apply time, so a plan never holds one.
func (s *Server) createEnvSetNames(r *http.Request, projectID uuid.UUID, name string, keys []envCreateKey, confirm []byte, actor uuid.UUID) (store.EnvSet, error) {
	if needsSecretsKey(keys) && s.Secrets == nil {
		return store.EnvSet{}, errSecretsKey
	}
	in := make([]store.EnvKeyCreate, 0, len(keys))
	for _, k := range keys {
		item := store.EnvKeyCreate{Key: k.Key, Secret: k.IsSecret, Generated: k.Generate != nil}
		if item.Generated || item.Secret {
			plain := ""
			if item.Generated {
				value, err := k.Generate.NewValue()
				if err != nil {
					return store.EnvSet{}, err
				}
				plain = value
			}
			sealed, err := s.sealValue(projectID, name, k.Key, plain)
			if err != nil {
				return store.EnvSet{}, err
			}
			item.Nonce, item.Ciphertext, item.KeyVersion = sealed.Nonce, sealed.Ciphertext, sealed.KeyVersion
		}
		in = append(in, item)
	}
	set, err := s.Store.CreateEnvSetNames(r.Context(), projectID, name, in, confirm, actor, s.now())
	if err != nil {
		return store.EnvSet{}, err
	}
	return createdEnvSetBody(set), nil
}

// needsSecretsKey reports whether any key is sealed: a generated key or a
// secret placeholder. A set of plain placeholders needs no secrets key.
func needsSecretsKey(keys []envCreateKey) bool {
	for _, k := range keys {
		if k.Generate != nil || k.IsSecret {
			return true
		}
	}
	return false
}

// createdEnvSetBody fills previews without decrypting: every secret key of
// a new set is generated or empty, so its preview is four bullets.
func createdEnvSetBody(set store.EnvSet) store.EnvSet {
	set = fillEnvSet(set)
	for i := range set.Keys {
		if set.Keys[i].IsSecret {
			preview := catalog.SecretPreview("")
			set.Keys[i].Preview = &preview
			set.Keys[i].Value = nil
		}
	}
	return set
}

func (s *Server) envSetCreateErr(w http.ResponseWriter, name string, err error) {
	switch {
	case errors.Is(err, store.ErrConflict):
		writeCode(w, "conflict", fmt.Sprintf("env set %s already exists", name))
	case errors.Is(err, store.ErrNotFound):
		writeCode(w, "not_found", "not found")
	case errors.Is(err, store.ErrInvalid):
		s.writeErr(w, err, false)
	default:
		s.secretWriteErr(w, err)
	}
}

func (s *Server) auditEnvSetCreate(r *http.Request, p principal, projectID uuid.UUID, name string, keys []envCreateKey, via string) {
	names := make([]string, 0, len(keys))
	generated := map[string]string{}
	placeholders := []string{}
	for _, k := range keys {
		names = append(names, k.Key)
		if k.Generate != nil {
			generated[k.Key] = k.Generate.Kind
		} else {
			placeholders = append(placeholders, k.Key)
		}
	}
	s.auditOK(r.Context(), p, store.AuditRow{
		ProjectID: idPtr(projectID),
		Action:    audit.ActionEnvSetCreate,
		Via:       via,
		Detail:    map[string]any{"set": name, "keys": names, "generated": generated, "placeholders": placeholders},
	})
}

// envSetCreateRequestHash binds the project, the set name, and the
// normalized keys. The idempotency key is not part of it.
func envSetCreateRequestHash(projectID uuid.UUID, name string, plan []byte) []byte {
	raw := `{"action":"env_set.create","name":` + jsonQuote(name) +
		`,"project_id":` + jsonQuote(projectID.String()) + `,"plan":` + string(plan) + `}`
	sum := sha256.Sum256([]byte(raw))
	return sum[:]
}

// envSetCreatePlan is the plan sentence (api-v1 v1.27 item 4). Set and key
// names are validated tokens, so nothing needs quoting, and no value exists.
func envSetCreatePlan(name string, keys []envCreateKey) string {
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		if k.Generate == nil {
			parts = append(parts, k.Key+" (empty; fill it in the console)")
			continue
		}
		desc := "generated " + k.Generate.Kind
		if n := k.Generate.Chars(); n > 0 {
			desc += fmt.Sprintf(", %d characters", n)
		}
		parts = append(parts, k.Key+" ("+desc+", secret)")
	}
	return "create env set " + name + " with " + strings.Join(parts, ", ")
}

// issueEnvSetCreate stores a delegated plan and answers 202. A set that
// already exists replays this key's stored answer (the confirm created it)
// or is a conflict.
func (s *Server) issueEnvSetCreate(w http.ResponseWriter, r *http.Request, p principal, projectID uuid.UUID, name string, keys []envCreateKey, key string) {
	planBody, err := json.Marshal(envCreatePlanBody{Keys: keys})
	if err != nil {
		s.fail(w, err)
		return
	}
	reqHash := envSetCreateRequestHash(projectID, name, planBody)
	if _, err := s.Store.GetEnvSet(r.Context(), projectID, name); err == nil {
		if s.replayStoredIdempotency(w, r, p.User.ID, key, reqHash) {
			return
		}
		writeCode(w, "conflict", fmt.Sprintf("env set %s already exists", name))
		return
	} else if !errors.Is(err, store.ErrNotFound) {
		s.fail(w, err)
		return
	}
	if !catalog.ValidIdempotencyKey(key) {
		writeCode(w, "bad_request", "invalid idempotency_key")
		return
	}
	if !s.claimOrReplay(w, r, p.User.ID, key, reqHash) {
		return
	}
	plain, tokenHash, err := secret.NewToken()
	if err != nil {
		s.failClaimed(w, r, p.User.ID, key, err)
		return
	}
	now := s.now().UTC()
	expires := now.Add(store.ConfirmationTTL)
	row := store.EnvSetConfirmation{
		UserID: p.User.ID, ProjectID: projectID, SetName: name, Body: planBody,
		RequestHash: reqHash, IdempotencyKey: key, CreatedAt: now, ExpiresAt: expires,
	}
	if err := s.Store.PutEnvSetConfirmation(r.Context(), tokenHash, row); err != nil {
		s.failClaimed(w, r, p.User.ID, key, err)
		return
	}
	payload := map[string]any{
		"confirmation_id": plain,
		"plan":            envSetCreatePlan(name, keys),
		"expires_at":      expires.Format(time.RFC3339),
	}
	out := envelopeRaw("ok", "ok", payload)
	s.finishIdempotency(r.Context(), p.User.ID, key, http.StatusAccepted, out)
	s.auditOK(r.Context(), p, store.AuditRow{
		ProjectID: idPtr(projectID),
		Action:    audit.ActionEnvSetWriteConfirmation,
		Detail:    map[string]any{"set": name},
	})
	writeJSON(w, http.StatusAccepted, out)
}

// confirmEnvSetCreate runs when the id matched no earlier confirmation
// table. The plan check, the create, and the plan delete commit together;
// a conflict leaves the plan unused.
func (s *Server) confirmEnvSetCreate(w http.ResponseWriter, r *http.Request, p principal, hash []byte, key string) {
	c, err := s.Store.GetEnvSetConfirmation(r.Context(), hash)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			writeCode(w, "not_found", "not found")
			return
		}
		s.fail(w, err)
		return
	}
	if c.UserID != p.User.ID || c.UsedAt != nil || !c.ExpiresAt.After(s.now()) {
		writeCode(w, "not_found", "not found")
		return
	}
	if key != c.IdempotencyKey {
		writeCode(w, "conflict", "idempotency_key does not match the request that issued this confirmation")
		return
	}
	if err := authz.Authorize(r.Context(), p.User.ID, c.ProjectID, authz.CapMembers); err != nil {
		s.deny(w, r, p, idPtr(c.ProjectID), nil, nil, audit.ActionEnvSetCreate, err)
		return
	}
	var plan envCreatePlanBody
	if err := json.Unmarshal(c.Body, &plan); err != nil || len(plan.Keys) == 0 {
		s.fail(w, errors.New("env set plan body"))
		return
	}
	set, err := s.createEnvSetNames(r, c.ProjectID, c.SetName, plan.Keys, hash, p.User.ID)
	if err != nil {
		s.envSetCreateErr(w, c.SetName, err)
		return
	}
	s.auditEnvSetCreate(r, p, c.ProjectID, c.SetName, plan.Keys, viaKind(p.Session.Kind))
	// A delegated session only ever sees the item 5 names-only shape, here
	// and in the stored answer an idempotent replay returns.
	var payload any = set
	if p.Session.Kind == store.KindDelegated {
		payload = namesOnly(set)
	}
	out := envelopeRaw("ok", "ok", payload)
	s.finishIdempotency(r.Context(), p.User.ID, c.IdempotencyKey, http.StatusCreated, out)
	writeJSON(w, http.StatusCreated, out)
}

// envKeyNamesOnly is the delegated env set read (api-v1 v1.27 item 5): no
// value, not even for a plain key, and no preview.
type envKeyNamesOnly struct {
	Key           string `json:"key"`
	IsSecret      bool   `json:"is_secret"`
	RevealPending bool   `json:"reveal_pending"`
	NeedsValue    bool   `json:"needs_value"`
}

type envSetNamesOnly struct {
	Name      string            `json:"name"`
	Keys      []envKeyNamesOnly `json:"keys"`
	UpdatedAt time.Time         `json:"updated_at"`
	UpdatedBy uuid.UUID         `json:"updated_by"`
}

func namesOnly(set store.EnvSet) envSetNamesOnly {
	out := envSetNamesOnly{Name: set.Name, Keys: make([]envKeyNamesOnly, 0, len(set.Keys)), UpdatedAt: set.UpdatedAt, UpdatedBy: set.UpdatedBy}
	for _, k := range set.Keys {
		out.Keys = append(out.Keys, envKeyNamesOnly{Key: k.Key, IsSecret: k.IsSecret, RevealPending: k.RevealPending, NeedsValue: k.NeedsValue})
	}
	return out
}
